<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/admin-functions.php';initSession();requireLogin();requirePermission('view_logs');
$logs=getActivityLogs(200);$securityLogs=[];try{$securityLogs=getDB()->query('SELECT a.*,u.first_name,u.last_name FROM auth_security_logs a LEFT JOIN users u ON u.user_id=a.user_id ORDER BY a.log_id DESC LIMIT 200')->fetchAll();}catch(PDOException $e){}$pageTitle='Activity Logs';require __DIR__.'/../components/header-admin.php';$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<div class="page-header"><div><h1>Activity Logs</h1><p>Recent actions from all users, including submissions, reviews and publishing.</p></div></div>
<div class="data-card p-4 table-responsive"><table class="table"><thead><tr><th>When</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?= $e($log['created_at']) ?></td><td><?= $e($log['first_name'].' '.$log['last_name']) ?></td><td><?= $e($log['action']) ?></td><td><?= $e($log['description']) ?></td></tr><?php endforeach;?></tbody></table></div>
<div class="data-card p-4 table-responsive mt-4"><h2 class="data-card-title mb-3">Login and password security</h2><table class="table"><thead><tr><th>When</th><th>User</th><th>Action</th><th>IP address</th><th>Details</th></tr></thead><tbody><?php foreach($securityLogs as $log):?><tr><td><?= $e($log['created_at']) ?></td><td><?= $e($log['user_id']?trim(($log['first_name']??'').' '.($log['last_name']??'')):'Unidentified account') ?></td><td><?= $e($log['action']) ?></td><td><?= $e($log['ip_address']) ?></td><td><?= $e($log['description']) ?></td></tr><?php endforeach;?></tbody></table><?php if(!$securityLogs):?><p>No security events available.</p><?php endif;?></div>
<?php require __DIR__.'/../components/footer-admin.php';?>
